*{box-sizing:border-box} :root{color-scheme:dark;--bg:#101211;--panel:#171a18;--line:#303531;--muted:#878d87;--paper:#f1f0e9;--lime:#d7ff63;--orange:#ff735b;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif} html,body{margin:0;min-height:100%;background:var(--bg);color:var(--paper);font-family:var(--sans)}body{min-height:100vh;background-image:radial-gradient(ellipse at 30% 5%,#252a251e,transparent 58%),linear-gradient(90deg,transparent 49.9%,#ffffff04 50%,transparent 50.1%);overflow-x:hidden}.shell{width:min(1360px,100%);margin:0 auto;padding:0 36px}.topbar{height:74px;border-bottom:1px solid #ffffff15;display:flex;align-items:center;justify-content:space-between}.wordmark{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--paper);font-weight:700;font-size:16px;letter-spacing:.1em}.brand-mark{background:var(--lime);color:#171a18;width:25px;height:25px;border-radius:6px;display:grid;place-items:center;font-size:15px;transform:rotate(-5deg)}.top-note,.sound-button,.eyebrow,.shift-tag,.card-label,.timer-sub,.legend,.tip,footer,.restart-button,.key-note,.quip-by,.score-row,.sticker{font-family:var(--mono);letter-spacing:.045em}.top-note{font-size:10px;color:#929990;display:flex;gap:9px;align-items:center}.top-note i,.live-dot{height:6px;width:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 11px #d7ff6390}.sound-button{border:1px solid #ffffff21;background:#ffffff06;color:#c5c8c0;padding:9px 12px;border-radius:6px;font-size:12px;cursor:pointer}.sound-button span{font-size:9px;margin-left:5px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:22px;padding-top:33px;padding-bottom:24px}.game-column{min-width:0}.game-heading{display:flex;align-items:flex-end;justify-content:space-between;padding:0 1px 18px}.eyebrow{font-size:9px;color:#a6ada4;margin:0 0 8px;letter-spacing:.13em}.game-heading h1{font-size:clamp(28px,3vw,39px);line-height:1;margin:0;letter-spacing:-.06em;font-weight:600}.game-heading h1 em,.screen-card h2 em{font-family:Georgia,serif;font-weight:400;color:var(--lime);letter-spacing:-.065em}.shift-tag{font-size:9px;color:#a1a69f;border:1px solid #ffffff18;padding:8px 10px;border-radius:4px;display:flex;align-items:center;gap:8px;margin-bottom:3px}.live-dot{width:5px;height:5px}.canvas-wrap{position:relative;width:100%;aspect-ratio:1.6;background:#232923;overflow:hidden;border:1px solid #ffffff20;border-radius:7px;box-shadow:0 20px 70px #0006;isolation:isolate}canvas{width:100%;height:100%;display:block}.screen{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#0d100edb,#111610b9 49%,#101310aa);z-index:2;backdrop-filter:blur(2px);transition:opacity .25s}.screen.hidden{opacity:0;pointer-events:none}.screen-card{width:min(390px,85%);position:relative}.intro-card{margin-left:-7%}.screen-card .eyebrow{color:var(--lime);font-size:9px;margin-bottom:15px}.screen-card h2{font-size:54px;line-height:.96;letter-spacing:-.07em;margin:0 0 17px;font-weight:600}.screen-card h2 em{font-size:1.08em}.screen-copy{max-width:330px;color:#bdc2b9;font-size:13px;line-height:1.65;margin:0 0 23px}.screen-copy b{color:#fff;font-weight:600}.primary-button{background:var(--lime);color:#171b14;border:0;border-radius:4px;padding:13px 15px;font-family:var(--mono);font-size:10px;font-weight:500;letter-spacing:.07em;cursor:pointer;min-width:150px;display:flex;justify-content:space-between;align-items:center;transition:transform .15s,background .15s}.primary-button:hover{transform:translateY(-2px);background:#e5ff9b}.primary-button span{font-size:17px}.key-note{font-size:8px;color:#919990;margin-top:18px}.key-note kbd,.restart-button kbd{font-family:var(--mono);font-size:8px;border:1px solid #ffffff38;border-radius:3px;padding:3px 4px;color:#dbded6;margin:0 3px}.key-note>span{padding:0 4px;color:var(--lime)}.sticker{position:absolute;top:-26px;right:-27px;transform:rotate(8deg);font-size:7px;color:#1c2118;background:var(--lime);padding:7px 8px;border-radius:3px;font-weight:500}.sticker span{font-size:10px;margin-left:4px}.screen-scribble{position:absolute;right:9%;bottom:18%;font:italic 16px/1.1 Georgia,serif;color:#d7ff6388;transform:rotate(-9deg)}.end-card{margin:0 auto;text-align:left}.end-card h2{font-size:45px}.end-icon{font-size:24px;color:var(--lime);margin-bottom:13px}.score-row{border-top:1px solid #ffffff25;border-bottom:1px solid #ffffff25;padding:11px 0;margin:0 0 18px;display:grid;grid-template-columns:1fr auto;gap:7px;font-size:8px;color:#a4aaa2}.score-row b{color:var(--lime);font-weight:400;text-align:right}.end-card .primary-button{width:160px}.control-row{height:39px;display:flex;align-items:center;justify-content:space-between}.legend,.tip{font-size:8px;color:#868d85}.legend{display:flex;align-items:center;gap:7px}.legend-dot{width:7px;height:7px;border-radius:2px;display:inline-block;margin-left:8px}.file-dot{background:var(--lime);margin-left:0}.boss-dot{background:var(--orange)}.tip{color:#727971}.sidebar{display:flex;flex-direction:column;gap:11px;padding-top:2px}.stat-card{border:1px solid #ffffff18;background:linear-gradient(145deg,#191d1a,#151816);border-radius:6px;padding:15px 15px}.card-label{font-size:8px;color:#989f96;display:flex;align-items:center;justify-content:space-between;letter-spacing:.08em}.card-label span{color:#757d73}.objective-card{padding-bottom:10px}.objective{height:36px;border-bottom:1px solid #ffffff0e;display:flex;align-items:center;gap:9px;font-size:10px;color:#c2c7bd}.objective:last-child{border:0}.objective-check{color:#777f74;font-family:var(--mono);font-size:8px}.objective b{margin-left:auto;font:10px var(--mono);color:var(--lime);white-space:nowrap}.objective b span{color:#768071}.objective .alert-word{color:#d7ff63}.objective .exit-status{color:#7b8478;font-size:8px}.alert-card{padding-bottom:14px}.meter{height:7px;background:#282e28;border-radius:10px;margin:17px 0 9px;position:relative;overflow:visible}.meter-fill{height:100%;width:0;border-radius:10px;background:var(--lime);box-shadow:0 0 12px #d7ff6355;transition:width .12s,background .2s}.meter-fill.danger{background:var(--orange);box-shadow:0 0 12px #ff735b55}.meter-tick{position:absolute;height:11px;top:-2px;border-left:1px solid #111511}.t1{left:33%}.t2{left:66%}.t3{left:100%}.alert-card p{color:#858d82;font-size:9px;margin:0}.time-card{padding-bottom:13px}.timer{font:33px var(--mono);letter-spacing:-.07em;color:var(--paper);margin:10px 0 0}.timer-sub{font-size:7px;color:#798177;margin-top:2px}.quip-card{position:relative;min-height:101px;padding:14px 15px;background:#d7ff63;border-radius:5px;color:#1a2114;overflow:hidden}.quip-card:after{content:'';position:absolute;right:-25px;bottom:-38px;width:100px;height:100px;border:1px solid #1d281a2c;border-radius:50%;box-shadow:0 0 0 12px #1d281a12,0 0 0 25px #1d281a0b}.quote-mark{font:35px Georgia,serif;line-height:.5}.quip-card p{font-size:14px;line-height:1.1;font-weight:600;letter-spacing:-.04em;margin:3px 0 7px}.quip-by{font-size:7px;color:#3e4935}.restart-button{background:transparent;border:0;text-align:left;color:#969d94;padding:6px 2px;font-size:8px;cursor:pointer}.restart-button:hover{color:var(--lime)}.restart-button kbd{float:right;color:#9da49a;border-color:#ffffff20}footer{border-top:1px solid #ffffff15;height:43px;display:flex;align-items:center;justify-content:space-between;font-size:7px;color:#666e66;letter-spacing:.11em}.pause-badge{position:absolute;top:15px;left:50%;transform:translateX(-50%);z-index:3;font:10px var(--mono);letter-spacing:.12em;background:#121612eb;border:1px solid #ffffff32;border-radius:4px;padding:9px 12px;color:var(--lime)}.pause-badge span{font-size:8px;color:#adb4a9}.pause-badge.hidden{display:none}.mobile-pad{display:none}
@media(max-width:900px){.shell{padding:0 22px}.game-layout{grid-template-columns:minmax(0,1fr) 235px;gap:14px}.game-heading h1{font-size:32px}.shift-tag{font-size:8px}.stat-card{padding:13px}.objective{font-size:9px}.sidebar{gap:9px}}
@media(max-width:700px){.shell{padding:0 14px;padding-bottom:135px}.topbar{height:57px}.top-note{display:none}.sound-button{padding:8px}.game-layout{display:flex;flex-direction:column;padding-top:22px;gap:10px}.game-heading{padding-bottom:12px;align-items:end}.game-heading h1{font-size:30px}.game-heading .eyebrow{font-size:7px}.shift-tag{font-size:7px;padding:7px 8px}.canvas-wrap{aspect-ratio:1.18}.screen-card{width:80%}.intro-card{margin-left:-5%}.screen-card h2{font-size:44px}.screen-copy{font-size:11px;margin-bottom:16px;max-width:280px}.key-note{font-size:7px;margin-top:12px}.screen-scribble{right:4%;bottom:9%;font-size:12px}.sticker{right:-16px;top:-20px;font-size:6px}.control-row{height:29px}.tip{display:none}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:8px}.objective-card{grid-column:span 2}.stat-card{padding:11px}.objective{height:30px}.alert-card p{font-size:8px}.timer{font-size:27px}.quip-card{min-height:94px;padding:11px}.quip-card p{font-size:12px}.restart-button{grid-column:span 2}footer{height:auto;min-height:44px;font-size:6px;gap:12px}.mobile-pad{position:fixed;z-index:5;bottom:env(safe-area-inset-bottom,0);left:0;right:0;height:119px;padding:10px 18px 14px;background:linear-gradient(0deg,#101211 72%,#10121100);display:flex;align-items:center;justify-content:space-between;pointer-events:none}.pad-cross{width:136px;height:100px;position:relative;pointer-events:auto}.pad-cross button{position:absolute;width:39px;height:34px;border:1px solid #ffffff28;background:#1a201b;color:var(--lime);border-radius:6px;font-size:13px;touch-action:none}.pad-cross button:active,.sprint-button:active{background:#38432d}.pad-cross button[data-dir=up]{top:0;left:48px}.pad-cross button[data-dir=left]{top:35px;left:7px}.pad-cross button[data-dir=down]{top:35px;left:48px}.pad-cross button[data-dir=right]{top:35px;left:89px}.sprint-button{pointer-events:auto;touch-action:none;width:84px;height:54px;border:1px solid #d7ff6355;border-radius:50%;background:#1b211a;color:var(--lime);font:8px var(--mono);letter-spacing:.1em}.screen-card .primary-button{padding:11px 13px}.end-card h2{font-size:39px}.score-row{font-size:7px}.screen-scribble{display:none}}
@media(max-width:390px){.game-heading h1{font-size:26px}.shift-tag{font-size:6px}.game-heading .eyebrow{font-size:6px}.canvas-wrap{aspect-ratio:1.08}.screen-card h2{font-size:39px}.screen-copy{font-size:10px}.sidebar{grid-template-columns:1fr 1fr}.objective-card{grid-column:span 2}.key-note{font-size:6px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const $ = (id) => document.getElementById(id);
  const ui = {
    start: $('startScreen'), end: $('endScreen'), startButton: $('startButton'), again: $('againButton'),
    restart: $('restartButton'), count: $('fileCount'), alertFill: $('alertFill'), alertPercent: $('alertPercent'),
    alertWord: $('alertWord'), alertHint: $('alertHint'), exit: $('exitStatus'), timer: $('timer'),
    pause: $('pauseBadge'), sound: $('soundButton'), mobilePad: $('mobilePad'), sprint: $('sprintButton'),
    endIcon: $('endIcon'), endEyebrow: $('endEyebrow'), endTitle: $('endTitle'), endCopy: $('endCopy'),
    finalScore: $('finalScore'), finalTime: $('finalTime'), quip: $('quip')
  };
  const desks = [
    {x:185,y:110,w:135,h:64}, {x:420,y:100,w:125,h:60}, {x:690,y:125,w:145,h:65},
    {x:175,y:270,w:145,h:65}, {x:410,y:260,w:145,h:64}, {x:680,y:300,w:145,h:64},
    {x:265,y:430,w:135,h:58}, {x:540,y:440,w:135,h:58}
  ];
  const fileSpots = [
    {x:82,y:85}, {x:365,y:202}, {x:603,y:85}, {x:880,y:250},
    {x:615,y:390}, {x:448,y:535}, {x:83,y:365}, {x:866,y:520}
  ];
  const patrol = [{x:584,y:213},{x:641,y:215},{x:644,y:390},{x:858,y:390},{x:857,y:215},{x:740,y:215}];
  const quips = [
    'Per my last email,<br>I was never here.', 'My camera is off<br>for bandwidth.', 'Let’s circle back<br>never.',
    'This could’ve been<br>a Slack message.', 'I am aligned with<br>leaving early.', 'Moving this to<br>my personal drive.'
  ];
  let state = 'ready', lastTime = 0, timeLeft = 75, attention = 0, collected = 0, soundOn = true, audio = null, quipIndex = 0;
  let player = {x:78,y:530,r:12,face:0}, boss = {x:584,y:213,angle:0,target:1,scan:0};
  let files = [], keys = new Set(), touchDirs = new Set(), sprintHeld = false, walkCycle = 0, flash = 0;

  function reset() {
    state = 'running'; lastTime = performance.now(); timeLeft = 75; attention = 0; collected = 0; flash = 0;
    player = {x:78,y:530,r:12,face:-Math.PI/2}; boss = {x:584,y:213,angle:0,target:1,scan:0};
    files = fileSpots.map(p => ({...p,got:false,phase:Math.random()*6.28}));
    ui.start.classList.add('hidden'); ui.end.classList.add('hidden'); ui.pause.classList.add('hidden');
    ui.count.innerHTML = '00<span> / 08</span>'; ui.exit.textContent = 'LOCKED'; ui.exit.style.color = '';
    ui.timer.textContent = '01:15'; ui.quip.innerHTML = quips[0]; quipIndex = 0; updateAlert();
  }
  function startAudio() { if (!audio) { try { audio = new (window.AudioContext || window.webkitAudioContext)(); } catch (_) {} } if (audio && audio.state === 'suspended') audio.resume(); }
  function beep(freq=520,duration=.08,type='sine',volume=.035) {
    if (!soundOn || !audio) return;
    const osc=audio.createOscillator(), gain=audio.createGain(); osc.type=type; osc.frequency.value=freq;
    gain.gain.setValueAtTime(volume,audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);
    osc.connect(gain); gain.connect(audio.destination); osc.start(); osc.stop(audio.currentTime+duration);
  }
  function rectCircleHit(cx,cy,r,rect) {
    const x=Math.max(rect.x,Math.min(cx,rect.x+rect.w)), y=Math.max(rect.y,Math.min(cy,rect.y+rect.h));
    return (cx-x)**2+(cy-y)**2 < r*r;
  }
  function blocked(x,y,r=12) {
    if(x<34+r||x>W-34-r||y<34+r||y>H-34-r) return true;
    return desks.some(d=>rectCircleHit(x,y,r,d));
  }
  function lineBlocked(ax,ay,bx,by) {
    const steps=30;
    for(let i=1;i<steps;i++){const t=i/steps,x=ax+(bx-ax)*t,y=ay+(by-ay)*t;if(desks.some(d=>x>d.x-4&&x<d.x+d.w+4&&y>d.y-4&&y<d.y+d.h+4))return true;}
    return false;
  }
  function movePlayer(dx,dy,dt) {
    const mag=Math.hypot(dx,dy); if(mag>0){dx/=mag;dy/=mag;player.face=Math.atan2(dy,dx);}
    const running=sprintHeld||keys.has('Shift'); const speed=running?216:145;
    const mx=dx*speed*dt,my=dy*speed*dt;
    let nx=player.x+mx;if(!blocked(nx,player.y))player.x=nx;
    let ny=player.y+my;if(!blocked(player.x,ny))player.y=ny;
    if(mag>0){walkCycle+=dt*(running?13:8); if(running) attention=Math.min(100,attention+dt*4.3);}
  }
  function canBossSee() {
    const dx=player.x-boss.x,dy=player.y-boss.y,dist=Math.hypot(dx,dy);
    if(dist>255||lineBlocked(boss.x,boss.y,player.x,player.y))return 0;
    const a=Math.atan2(dy,dx),delta=Math.atan2(Math.sin(a-boss.angle),Math.cos(a-boss.angle));
    const half=.63;
    if(Math.abs(delta)>half)return 0;
    return (1-dist/310)*(1-Math.abs(delta)/half*.3);
  }
  function updateBoss(dt) {
    const goal=patrol[boss.target],dx=goal.x-boss.x,dy=goal.y-boss.y,dist=Math.hypot(dx,dy);
    if(dist<8){boss.target=(boss.target+1)%patrol.length;boss.scan=1.1;}
    else {const speed=42;boss.x+=dx/dist*speed*dt;boss.y+=dy/dist*speed*dt;boss.angle=Math.atan2(dy,dx);}
    if(boss.scan>0){boss.scan-=dt;boss.angle+=Math.sin(performance.now()/370)*dt*1.6;}
    const seen=canBossSee();
    if(seen>0) attention=Math.min(100,attention+dt*(22+seen*26));
    else attention=Math.max(0,attention-dt*(sprintHeld||keys.has('Shift')?7:13));
    if(attention>=100){finish(false,'caught');}
  }
  function update(dt) {
    if(state!=='running')return;
    timeLeft-=dt; if(timeLeft<=0){timeLeft=0;finish(false,'late');return;}
    const x=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0)+(touchDirs.has('right')?1:0)-(touchDirs.has('left')?1:0);
    const y=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0)+(touchDirs.has('down')?1:0)-(touchDirs.has('up')?1:0);
    movePlayer(x,y,dt); updateBoss(dt);
    files.forEach(f=>{if(!f.got&&Math.hypot(f.x-player.x,f.y-player.y)<24){f.got=true;collected++;attention=Math.max(0,attention-5);ui.count.innerHTML=String(collected).padStart(2,'0')+'<span> / 08</span>';beep(740+collected*45,.12,'triangle',.05);quipIndex=(quipIndex+1)%quips.length;ui.quip.innerHTML=quips[quipIndex];if(collected===8){ui.exit.textContent='OPEN';ui.exit.style.color='var(--lime)';}}});
    if(collected===8&&Math.hypot(player.x-900,player.y-57)<40){finish(true,'win');return;}
    updateAlert();
  }
  function updateAlert(){
    const n=Math.max(0,Math.min(100,attention));ui.alertFill.style.width=n+'%';ui.alertPercent.textContent=String(Math.round(n)).padStart(2,'0')+'%';
    ui.alertFill.classList.toggle('danger',n>57);
    ui.alertWord.textContent=n>72?'PANIC':n>38?'SUSPICIOUS':'LOW';
    ui.alertWord.style.color=n>72?'var(--orange)':n>38?'#ffbf63':'';
    ui.alertHint.textContent=n>72?'They are drafting the follow-up email.':n>38?'Someone is looking very busy.':n>8?'A little eye contact. Nothing serious.':'Completely invisible. As it should be.';
  }
  function finish(win,reason){
    if(state==='ended')return;state='ended';ui.end.classList.remove('hidden');
    if(win){ui.endIcon.textContent='✦';ui.endEyebrow.textContent='SHIFT COMPLETE';ui.endTitle.innerHTML='Beautifully<br><em>unemployed.</em>';ui.endCopy.textContent='You escaped with all your files. Your productivity score remains a mystery.';beep(880,.2,'triangle',.06);setTimeout(()=>beep(1175,.3,'triangle',.04),120);}
    else if(reason==='caught'){ui.endIcon.textContent='☹';ui.endEyebrow.textContent='QUICK CHAT?';ui.endTitle.innerHTML='We noticed<br><em>your absence.</em>';ui.endCopy.textContent='The manager caught you wandering. Maybe try using the furniture next time.';beep(170,.35,'sawtooth',.05);}
    else{ui.endIcon.textContent='◷';ui.endEyebrow.textContent='CALENDAR INVITE: NOW';ui.endTitle.innerHTML='The meeting<br><em>found you.</em>';ui.endCopy.textContent='Time ran out before you could make your graceful exit. Don’t accept the follow-up.';beep(220,.25,'triangle',.04);}
    ui.finalScore.textContent=String(collected).padStart(2,'0')+' / 08';ui.finalTime.textContent='00:'+String(Math.ceil(timeLeft)).padStart(2,'0');
  }
  function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
  function drawFloor(){
    ctx.fillStyle='#252d27';ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#29322b';ctx.fillRect(34,34,W-68,H-68);
    for(let y=42;y<H-35;y+=48){ctx.strokeStyle=y%96===42?'#d9e3ce0a':'#d9e3ce06';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(W-35,y);ctx.stroke();}
    for(let x=45;x<W-35;x+=64){ctx.strokeStyle='#d9e3ce05';ctx.beginPath();ctx.moveTo(x,35);ctx.lineTo(x,H-35);ctx.stroke();}
    // perimeter walls and windows
    ctx.fillStyle='#18201b';ctx.fillRect(0,0,W,34);ctx.fillRect(0,H-34,W,34);ctx.fillRect(0,0,34,H);ctx.fillRect(W-34,0,34,H);
    for(let x=57;x<900;x+=116){ctx.fillStyle='#a1c5a526';roundRect(ctx,x,8,74,14,2);ctx.fill();ctx.strokeStyle='#a8c9ae40';ctx.stroke();}
    // floor lamp pools
    ctx.save();ctx.globalAlpha=.12;for(const p of [{x:120,y:220,r:100},{x:530,y:505,r:100},{x:860,y:460,r:95}]){const g=ctx.createRadialGradient(p.x,p.y,5,p.x,p.y,p.r);g.addColorStop(0,'#e1f19b');g.addColorStop(1,'#e1f19b00');ctx.fillStyle=g;ctx.fillRect(p.x-p.r,p.y-p.r,p.r*2,p.r*2);}ctx.restore();
  }
  function drawDesk(d,i){
    // subtle desk shadow
    ctx.fillStyle='#10161288';roundRect(ctx,d.x+5,d.y+8,d.w,d.h,5);ctx.fill();
    ctx.fillStyle='#39443b';roundRect(ctx,d.x,d.y,d.w,d.h,5);ctx.fill();
    ctx.fillStyle='#505d50';roundRect(ctx,d.x+3,d.y+2,d.w-6,d.h-8,4);ctx.fill();
    ctx.strokeStyle='#82927b42';ctx.lineWidth=1;roundRect(ctx,d.x+1,d.y+1,d.w-2,d.h-3,5);ctx.stroke();
    // laptop + papers + coffee
    const flip=i%2;ctx.fillStyle='#202b23';roundRect(ctx,d.x+(flip?14:d.w-56),d.y+10,43,29,3);ctx.fill();ctx.fillStyle='#86a074';roundRect(ctx,d.x+(flip?17:d.w-53),d.y+13,37,22,2);ctx.fill();
